import{_ as t,l,o as e,c as p,v as r,p as o,x as i,d,i as h,S as s}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"费马与欧拉定理","description":"","frontmatter":{"title":"费马与欧拉定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fermat-euler.md","filePath":"cs/fermat-euler.md","lastUpdated":1789023840000}'),m={name:"cs/fermat-euler.md"};function c(u,a,v,_,b,q){const n=l("Mermaid");return e(),p("div",null,[a[1]||(a[1]=r('<h1 id="费马与欧拉定理" tabindex="-1">费马与欧拉定理 <a class="header-anchor" href="#费马与欧拉定理" aria-label="Permalink to &quot;费马与欧拉定理&quot;">​</a></h1><div class="epigraph"><p>$p$ 素数、$p\\nmid a$ 则 $a^{p-1}\\equiv 1\\pmod p$；一般 $n$，$\\gcd(a,n)=1$ 则 $a^{\\varphi(n)}\\equiv 1\\pmod n$。模幂的指数可先模 $\\varphi(n)$。</p><footer>—— 据 Fermat；Euler；Ireland and Rosen, A Classical Introduction to Modern Number Theory 整理</footer></div><p>上一课<a href="/cs/euclid-extended">扩展欧几里得</a> 给出逆。缺口是<strong>乘法阶</strong>：逆也可以写成 \\(a^{\\varphi(n)-1}\\)，更重要的是把 \\(a^k\\) 的指数降到模 \\(\\varphi(n)\\)。RSA 明文运算依赖 \\(a^{ed}\\equiv a\\pmod n\\) 的欧拉（或 Carmichael）形式。本课不讲 RSA 协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\varphi(n)=|(\\mathbb{Z}/n\\mathbb{Z})^\\times|\\)。群论：有限群 \\(x^{|G|}=1\\)。欧拉定理即此。费马是 \\(n=p\\)，\\(\\varphi(p)=p-1\\)。\\(n=pq\\) 时 \\(\\varphi=(p-1)(q-1)\\)。Carmichael \\(\\lambda(n)\\) 是指数的最小万有上界，RSA 实现常用 \\(\\lambda\\) 代替 \\(\\varphi\\)，本课点名。</p><p>若 \\(\\gcd(a,n)\\ne 1\\)，欧拉不能直接用；\\(n=pq\\) 上对所有 \\(a\\) 仍有 \\(a^{k\\lambda}\\equiv a\\) 一类恒等式，证明用 CRT，后课。</p><h3 id="不是素性测试" tabindex="-1">不是素性测试 <a class="header-anchor" href="#不是素性测试" aria-label="Permalink to &quot;不是素性测试&quot;">​</a></h3><p>费马反推「\\(a^{n-1}\\equiv 1\\) 则 \\(n\\) 素」为假：Carmichael 数骗过所有与 \\(n\\) 互素的底。Miller–Rabin 后课。本课只要正向定理。</p><p><span class="marginnote">Euler 推广 Fermat。Ireland–Rosen 标准数论。Knuth 卷 2 模幂。主干 DH 的指数在模 \\(p\\) 的阶上，生成元课再写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用 \\(\\varphi\\) 算一次 \\(a^{-1}\\equiv a^{\\varphi(n)-1}\\) 并对比扩展欧几里得（后者更快）。写快速幂：平方乘 \\(O(\\log k)\\) 次乘。强调：先把 \\(k\\) 模 \\(\\varphi(n)\\) 再乘，必须已知 \\(\\varphi\\)——这正是 RSA 私钥。</p>',11)),(e(),o(s,null,{default:i(()=>[h(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GRP%5B%22(Z%2FnZ)%C3%97%20%E9%98%B6%20%CF%86(n)%22%5D%20--%3E%20EUL%5B%22a%5E%7B%CF%86(n)%7D%20%E2%89%A1%201%22%5D%0A%20%20EUL%20--%3E%20RED%5B%22%E6%8C%87%E6%95%B0%E6%A8%A1%20%CF%86(n)%22%5D%0A%20%20RED%20--%3E%20POW%5B%22%E5%BF%AB%E9%80%9F%E5%B9%82%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定理把「无穷指数」收成循环群上的算术。下一课 CRT 把模 \\(pq\\) 拆成模 \\(p\\) 与模 \\(q\\)，欧拉在两边分别用。本课不拆。</p><p>\\(\\varphi\\) 积性：\\(\\gcd(m,n)=1\\Rightarrow\\varphi(mn)=\\varphi(m)\\varphi(n)\\)。公式为后课素数生成铺路。</p><p>Carmichael \\(\\lambda(n)=\\mathrm{lcm}(\\lambda(p^k),\\ldots)\\)，对 \\(p^k\\) 有显式。RSA 用 \\(\\lambda(n)\\) 比 \\(\\varphi\\) 更小，指数更短。\\(\varphi\\) 积性证明用 CRT：模 \\(mn\\) 互素 \\(\\iff\\) 两侧都互素。费马小定理的「逆」不能当素性测试，Miller–Rabin 课再拆平方链。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证原根存在，不引入 Dirichlet。不写 RSA 加密函数。后课默认：互素时指数模 \\(\\varphi(n)\\)；\\(p\\) 素时模 \\(p-1\\)。下一课中国剩余定理。</p><p>指数先模 \\(\\varphi(n)\\) 再快速幂，前提是已知 \\(\\varphi\\)——RSA 私钥正在这里。正向定理不能当素性测试。CRT 下一课把模 \\(pq\\) 拆开，两边分别用费马。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>费马：\\(a^{p-1}\\equiv 1\\pmod p\\)；欧拉：\\(a^{\\varphi(n)}\\equiv 1\\pmod n\\)。</li><li>指数可约到 \\(\\varphi(n)\\) 或 \\(\\lambda(n)\\)。</li><li>不能当素性测试；Carmichael 数反例。</li><li>出处：Fermat；Euler；Ireland and Rosen。</li></ul>',9))])}const A=t(m,[["render",c]]);export{E as __pageData,A as default};
